STORY_DARK_FOREST_51_60 = (
    V2StoryQuestContentRecord('dark_forest_051_shadow_beyond_the_border', 51, 'Тінь за межею', 'TALK', 'dark_forest', 6, 'start_path_050_road_ahead', 'elder', 'elder', 1, 'Після перемоги над Ватажком Староста отримує тривожні повідомлення зі старого прикордонного шляху. Біля входу до Темного Бору з’явилися гоблінські дозори, а кілька мисливців не повернулися з лісу.', 'Поговорити зі Старостою про загрозу біля Темного Бору.', 'Перемога над Ватажком повернула спокій на дорогу через Початок Шляху, але ненадовго. Наші мисливці простежили рунічний слід до старого прикордонного шляху, що веде в Темний Бір.\n\nКілька тижнів тому там почали з’являтися гоблінські дозори. Спочатку вони ховалися серед дерев, але тепер перекривають стежки й не пропускають людей углиб лісу. Учора з розвідки не повернулися двоє мисливців.\n\nМіська варта не може вирушити туди без підготовки. Поки що ми знаємо лише те, що загроза з Початку Шляху не зникла, а простяглася до кордону Темного Бору.', 'Староста завершує доповідь про зниклих мисливців, гоблінські дозори та рунічний слід, що веде до Темного Бору.', 66, 1.84, {'reward_formula': None, 'next_route': {'npc_id': 'mercenary_head', 'route_text': '🏙️ Місто → 📜 Гільдія Найманців → ⚔️ Голова Найманців'}, 'location_access_policy': {'story_hint_only': True, 'does_not_bypass_unlock': True, 'canonical_unlock_level': 6}}),
    V2StoryQuestContentRecord('dark_forest_052_dark_forest_border', 52, 'Межа Темного Бору', 'KILL_REGION', 'dark_forest', 6, 'dark_forest_051_shadow_beyond_the_border', 'mercenary_head', 'mercenary_head', 8, 'Голова Найманців просить перевірити прикордонні стежки Темного Бору, відтіснити перші дозори й створити безпечний прохід для розвідників.', 'Перемогти 8 будь-яких істот у локації Темний Бір.', 'Староста вже передав мені звістку. Гобліни ніколи не підходили так близько до кордону. Раніше вони трималися в глибині лісу й нападали лише на необережних мандрівників. Тепер їхні дозори ходять уздовж старого шляху, наче охороняють встановлену межу.\n\nМи не зможемо розпочати пошуки зниклих мисливців, поки стежки контролюють ворожі загони. Вирушай у Темний Бір і відтісни тих, хто тримає підступи до лісу.\n\nНе намагайся заходити надто далеко. Зараз нам потрібно лише відкрити шлях для розвідки й перевірити, наскільки серйозно гобліни укріпили кордон.', 'Перші дозори відступили вглиб лісу. Розвідники Гільдії Найманців отримали можливість оглянути старий шлях і помітили, що гобліни діють організовано.', 66, 1.84, {'reward_formula': None, 'progress_text': 'Розвідка межі Темного Бору: {progress}/8'}),
    V2StoryQuestContentRecord('dark_forest_053_not_a_random_patrol', 53, 'Не випадковий дозор', 'TALK', 'dark_forest', 6, 'dark_forest_052_dark_forest_border', 'mercenary_head', 'mercenary_head', 1, 'Голова Найманців розповідає про результати розвідки: гобліни не просто блукають біля кордону, а позначають територію й передають сигнали між дозорами.', 'Отримати від Голови Найманців результати розвідки прикордонного шляху.', 'Розвідники повернулися зі старого шляху. Напади припинилися одразу після того, як ти відтіснив передові загони, але гобліни не розбіглися. Вони відійшли до лісу й зайняли нові позиції.\n\nНа деревах уздовж стежки розвідники помітили зарубки, а між камінням були розкладені зв’язки сухих гілок. Це не випадкові сліди. Так гобліни позначають контрольовану територію й попереджають один одного про чужинців.', 'Голова Найманців завершує доповідь: зарубки й сигнальні зв’язки підтверджують, що гоблінські дозори координують дії та контролюють прикордонний шлях.', 66, 1.84, {'reward_formula': None}),
    V2StoryQuestContentRecord('dark_forest_054_sign_on_the_old_road', 54, 'Знак на старому шляху', 'QUEST_ITEM', 'dark_forest', 6, 'dark_forest_053_not_a_random_patrol', 'mercenary_head', 'mercenary_head', 1, 'Голова Найманців просить знайти гоблінський прикордонний знак біля старого шляху та зберегти його як доказ організованої присутності дозорів.', 'Шукати під час полювання доказ того, що гобліни позначають межі контрольованої території.', 'Знак має бути вирізаний із темного дерева й перев’язаний червоною мотузкою. Розвідники не стали торкатися його, бо поряд були свіжі сліди гоблінів.\n\nОбшукай місцевість під час полювання. Якщо знайдеш позначку, не ламай її й не викидай. Староста має побачити доказ, що гобліни не просто нападають на мандрівників, а встановлюють власний кордон біля міських земель.', 'На темній дерев’яній дощечці вирізаний символ гоблінського дозору. Червона мотузка свіжа, а на зворотному боці залишилися сліди смоли. Знак встановили нещодавно. Доказ потрібно передати Старості.', 66, 1.84, {'reward_formula': None, 'quest_item': {'item_key': 'dark_forest_goblin_patrol_border_sign', 'display_name': 'Прикордонний знак гоблінського дозору', 'quantity': 1, 'drop_chance': 0.15, 'drop_location_id': 'dark_forest', 'drop_message': '🧩 Сюжетна знахідка: Прикордонний знак гоблінського дозору'}, 'progress_text': 'Пошук прикордонного знака: {progress}/1', 'item_reveal_policy': {'pre_reveal_title': 'Знак на старому шляху', 'post_reveal_title': 'Знак на старому шляху', 'reveal_on_first_drop': True}, 'next_route': {'npc_id': 'elder', 'route_text': '🏙️ Місто → 🏛️ Ратуша → 🗣️ Староста'}}),
    V2StoryQuestContentRecord('dark_forest_055_border_that_never_existed', 55, 'Межа, якої не було', 'TURN_IN', 'dark_forest', 6, 'dark_forest_054_sign_on_the_old_road', 'elder', 'elder', 1, 'Передати Старості гоблінський прикордонний знак і підтвердити, що дозори намагаються встановити контроль над старим шляхом.', 'Передати Старості прикордонний знак гоблінського дозору.', 'Цей знак не схожий на випадковий трофей. Гобліни встановили його на нашому старому прикордонному шляху, де раніше проходили мисливці й торгові вози. Вони оголосили цю землю своєю без жодного нападу на місто й без відкритої вимоги.\n\nЯкщо за дозорами стоїть єдиний ватажок, він намагається відрізати Темний Бір від решти земель і приховати те, що відбувається в глибині.\n\nЯ залишу знак у Ратуші як доказ того, що гобліни свідомо встановлюють нову межу біля міських земель.', 'Староста приймає гоблінський знак і підтверджує, що дозори свідомо встановлюють новий кордон на старому прикордонному шляху.', 66, 1.84, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_goblin_patrol_border_sign', 'quantity': 1, 'consume': True}], 'next_route': {'npc_id': 'mercenary_head', 'route_text': '🏙️ Місто → 📜 Гільдія Найманців → ⚔️ Голова Найманців'}}),
    V2StoryQuestContentRecord('dark_forest_056_camp_by_the_road', 56, 'Табір біля дороги', 'KILL_REGION', 'dark_forest', 6, 'dark_forest_055_border_that_never_existed', 'mercenary_head', 'mercenary_head', 10, 'Голова Найманців наказує розчистити старий шлях і зруйнувати оборону тимчасового табору, з якого гобліни керують прикордонними дозорами.', 'Перемогти 10 будь-яких істот у локації Темний Бір.', 'Після твоєї знахідки ми повторно перевірили старий шлях. За першою лінією дозорів стоїть тимчасовий табір. Гобліни використовують його як перевалочний пункт: звідти виходять патрулі, туди приносять припаси й там змінюють варту.\n\nПоки табір діє, наші розвідники не зможуть пройти далі. Зачисти шлях і змусь його варту відступити вглиб Темного Бору.', 'Прикордонний табір утратив охорону. Гоблінські загони відступили, а старий шлях став доступним для подальшої розвідки.', 66, 1.84, {'reward_formula': None, 'progress_text': 'Зачистка табору біля дороги: {progress}/10'}),
    V2StoryQuestContentRecord('dark_forest_057_runic_trace', 57, 'Рунічний слід', 'QUEST_ITEM', 'dark_forest', 6, 'dark_forest_056_camp_by_the_road', 'mercenary_head', 'mercenary_head', 1, 'Після зачистки прикордонного табору Голова Найманців просить знайти предмет, який пояснить синювате світіння серед гоблінських трофеїв.', 'Шукати під час полювання предмет зі слідами рунічної корупції.', 'Розвідники бачили серед покинутих речей уламки темного металу. Частина з них була холодною, хоча лежала біля згаслого багаття, а на поверхні проступало синє світіння.\n\nМи вже бачили щось подібне біля лігва Ватажка, але ці уламки мають іншу форму. Можливо, гобліни носять їх як обереги або отримують від когось, хто володіє рунічною магією.\n\nПродовжуй полювання в Темному Борі й знайди цілий фрагмент. Не намагайся самостійно очищати або ламати його. Якщо це руна, предмет має оглянути Рунний Майстер.', 'На уламку темного металу збереглася частина руни. Її лінії світяться тим самим холодним світлом, яке було помітне на слідах корупції біля лігва Ватажка. Знахідку потрібно передати Рунному Майстру.', 66, 1.84, {'reward_formula': None, 'quest_item': {'item_key': 'dark_forest_runic_amulet_fragment', 'display_name': 'Уламок рунічного амулета', 'quantity': 1, 'drop_chance': 0.15, 'drop_location_id': 'dark_forest', 'drop_message': '🧩 Сюжетна знахідка: Уламок рунічного амулета'}, 'progress_text': 'Пошук рунічного уламка: {progress}/1', 'item_reveal_policy': {'pre_reveal_title': 'Рунічний слід', 'post_reveal_title': 'Рунічний слід', 'reveal_on_first_drop': True}, 'next_route': {'npc_id': 'rune_master', 'route_text': '🏙️ Місто → ⚒️ Ремісничий квартал → 💠 Рунний Майстер'}}),
    V2StoryQuestContentRecord('dark_forest_058_familiar_rune', 58, 'Знайома руна', 'TURN_IN', 'dark_forest', 6, 'dark_forest_057_runic_trace', 'rune_master', 'rune_master', 1, 'Передати Рунному Майстру уламок амулета й з’ясувати, чи пов’язаний він із корупцією, яка підсилювала Ватажка.', 'Передати Рунному Майстру уламок рунічного амулета.', 'Цей метал не належить старим міським рунам. Він грубо оброблений, але символ нанесено точно. Подивись на зламані лінії: у них повторюється той самий вузол, який ми бачили на слідах корупції біля лігва Ватажка.\n\nАмулет не створював силу сам по собі. Він проводив її від іншого джерела й передавав носієві. Ватажок міг отримати подібний предмет від тих самих істот, що зараз керують гоблінськими дозорами.\n\nЯ залишу уламок для подальшого дослідження. Його руна підтверджує зв’язок між подіями на Початку Шляху та загрозою у Темному Борі.', 'Рунний Майстер підтверджує: символ на амулеті належить до тієї самої системи рун, яка підсилювала Ватажка. Гоблінські дозори пов’язані з джерелом корупції в глибині Темного Бору.', 66, 1.84, {'reward_formula': None, 'required_quest_items': [{'item_key': 'dark_forest_runic_amulet_fragment', 'quantity': 1, 'consume': True}], 'next_route': {'npc_id': 'mercenary_head', 'route_text': '🏙️ Місто → 📜 Гільдія Найманців → ⚔️ Голова Найманців'}}),
    V2StoryQuestContentRecord('dark_forest_059_road_deeper', 59, 'Дорога вглиб', 'KILL_REGION', 'dark_forest', 6, 'dark_forest_058_familiar_rune', 'mercenary_head', 'mercenary_head', 10, 'Після висновку Рунного Майстра Голова Найманців наказує пробити безпечний шлях за прикордонні табори й визначити напрямок, звідки надходять рунічні амулети.', 'Перемогти 10 будь-яких істот у локації Темний Бір.', 'Тепер ми знаємо, що гобліни не самі створили ці амулети. Хтось постачає їм рунічні предмети й використовує дозори, щоб приховати шлях углиб лісу.\n\nНаші розвідники знайшли вузьку стежку за прикордонним табором. Вона веде до старих вирубок, але на кожному повороті стоять нові загони. Якщо очистити стежку, ми зможемо простежити рух гоблінів і знайти їхні основні табори.\n\nПробий шлях углиб Темного Бору. Не переслідуй тих, хто відступає надто далеко. Нам потрібен безпечний маршрут для наступної серії вилазок, а не необережний штурм невідомої фортеці.', 'Шлях за прикордонними таборами відкрито. Розвідники помітили сліди великої кількості гоблінів, що рухаються між кількома укріпленими стоянками. Це вже не окремі дозори, а впорядкована мережа таборів.', 66, 1.84, {'reward_formula': None, 'progress_text': 'Розчищення дороги вглиб: {progress}/10', 'next_route': {'npc_id': 'elder', 'route_text': '🏙️ Місто → 🏛️ Ратуша → 🗣️ Староста'}}),
    V2StoryQuestContentRecord('dark_forest_060_threat_from_the_depths', 60, 'Загроза з глибини', 'TURN_IN', 'dark_forest', 6, 'dark_forest_059_road_deeper', 'elder', 'elder', 1, 'Доповісти Старості про гоблінські табори, рунічні амулети та підтверджений зв’язок із корупцією, що підсилювала Ватажка.', 'Доповісти Старості про результати першої розвідки Темного Бору.', 'Отже, гобліни встановили власну межу, укріпили старий шлях і отримують рунічні амулети з глибини Темного Бору. Ватажок був не джерелом корупції, а лише одним із тих, кого вона підсилила.\n\nЦе пояснює, чому після його загибелі рунічний слід не зник. Хтось продовжує виготовляти або роздавати ці предмети, а гоблінські дозори захищають дорогу до джерела.\n\nТвоєї доповіді достатньо, щоб підтвердити: загроза Темного Бору організована й пов’язана з подіями на Початку Шляху. Перша розвідка завершена.', 'Староста приймає доповідь про гоблінські дозори та рунічний амулет. Перша розвідка підтвердила: події на Початку Шляху й загроза Темного Бору є частинами одного задуму.\n\nГобліни створили мережу укріплених таборів і отримують рунічні предмети від невідомої сили в глибині лісу.\n\n✅ Розділ «Тінь за Темним Бором» завершено.', 66, 1.84, {'reward_formula': None, 'required_quest_items': [], 'itemless_turn_in_policy': {'enabled': True, 'purpose': 'final_report', 'button_text': '🗣️ Доповісти Старості'}, 'next_quest_preview': {'number': 61, 'title': 'Наказ про вилазки', 'giver_npc_id': 'mercenary_head', 'unlock_level': 7}, 'next_route': {'npc_id': 'mercenary_head', 'route_text': '🏙️ Місто → 📜 Гільдія Найманців → ⚔️ Голова Найманців'}}),
)

def validate_story_dark_forest_51_60() -> None:
    quests=STORY_DARK_FOREST_51_60
    if len(quests)!=10 or [q.number for q in quests]!=list(range(51,61)): raise ValueError('invalid_package_identity')
    if len({q.quest_id for q in quests})!=10: raise ValueError('duplicate_quest_id')
    if quests[0].previous_quest_id!='start_path_050_road_ahead': raise ValueError('invalid_story_bridge')
    for previous,current in zip(quests,quests[1:]):
        if current.previous_quest_id!=previous.quest_id: raise ValueError('invalid_predecessor_chain')
    for quest in quests:
        if quest.unlock_level!=6 or quest.location_id!='dark_forest': raise ValueError('invalid_level_or_location')
        if quest.reward_exp!=66 or abs(quest.reward_gold-1.84)>1e-9: raise ValueError('invalid_reward_parity')

validate_story_dark_forest_51_60()
